def count_primes_in_range(a, b):
    if b < 2:
        return 0
    sieve = [True] * (b + 1)
    sieve[0] = False
    if b >= 1:
        sieve[1] = False
    for i in range(2, int(b ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, b + 1, i):
                sieve[j] = False
    return sum(1 for x in range(max(a, 2), b + 1) if sieve[x])

def classify_char_string(s):
    def classify(ch):
        if ch in 'aeiouAEIOU':
            return 'V'
        if ch.isalpha():
            return 'C'
        if ch.isdigit():
            return 'D'
        return 'O'
    return ''.join(map(classify, s))

