def add_days_iso_string(date_str, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def month_len(y, m):
        lens = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lens[m - 1]
    def leaps_before(y):
        y -= 1
        return y // 4 - y // 100 + y // 400
    def to_ordinal(y, m, d):
        return (y - 1) * 365 + leaps_before(y) + sum(month_len(y, mm) for mm in range(1, m)) + d
    def from_ordinal(total):
        y = 1
        while total > (366 if is_leap(y) else 365):
            total -= 366 if is_leap(y) else 365
            y += 1
        m = 1
        while total > month_len(y, m):
            total -= month_len(y, m)
            m += 1
        return y, m, total
    y, m, d = (int(p) for p in date_str.split('-'))
    ny, nm, nd = from_ordinal(to_ordinal(y, m, d) + n)
    return f"{ny:04d}-{nm:02d}-{nd:02d}"

