def meets_distinct_class_count_policy(s):
    if len(s) < 8:
        return False
    class_checks = [str.islower, str.isupper, str.isdigit, lambda c: not c.isalnum()]
    count = 0
    for check in class_checks:
        if any(check(ch) for ch in s):
            count += 1
    return count >= 3

