def wrap_text(text, width):
    words = text.split()
    lines = []
    for word in words:
        if lines and len(lines[-1]) + 1 + len(word) <= width:
            lines[-1] = lines[-1] + ' ' + word
        else:
            lines.append(word)
    return lines

